package nl.smartstreamlabs.sbwdroneconfig.mixin;
import nl.smartstreamlabs.sbwdroneconfig.*;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;
import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.entity.player.Player;
/** Real SBW crowbar containers retain their full entity NBT and deploy onto validated water. Other containers are untouched. */
@Mixin(value=com.atsuishio.superbwarfare.item.container.ContainerBlockItem.class,remap=false)
public abstract class Wd01ContainerMixin {
 @Inject(method="use",remap=false,at=@At("HEAD"),cancellable=true) private void wd01$water(Level l,Player p,InteractionHand h,CallbackInfoReturnable<InteractionResultHolder<ItemStack>> ci){if(ServiceContainers.is(p.getItemInHand(h),"ground_assault_drone_gad01")){ci.setReturnValue(AddonItems.GAD01.get().use(l,p,h));return;}if(ServiceContainers.is(p.getItemInHand(h),"submarine_drone_sd01")){ci.setReturnValue(AddonItems.SD01.get().use(l,p,h));return;}var naval=Ndc01Item.container(p.getItemInHand(h));if(naval!=null){ci.setReturnValue(Ndc01Item.deploy(l,p,h,naval));return;}var n=Wd01Item.container(p.getItemInHand(h));if(n!=null)ci.setReturnValue(Wd01Item.deploy(l,p,h,n));}
 @Inject(method="useOn",remap=false,at=@At("HEAD"),cancellable=true) private void wd01$waterOn(net.minecraft.world.item.context.UseOnContext c,CallbackInfoReturnable<InteractionResult> ci){if(c.getPlayer()==null)return;if(ServiceContainers.is(c.getItemInHand(),"ground_assault_drone_gad01")){ci.setReturnValue(AddonItems.GAD01.get().use(c.getLevel(),c.getPlayer(),c.getHand()).getResult());return;}if(ServiceContainers.is(c.getItemInHand(),"submarine_drone_sd01")){ci.setReturnValue(AddonItems.SD01.get().use(c.getLevel(),c.getPlayer(),c.getHand()).getResult());return;}var naval=Ndc01Item.container(c.getItemInHand());if(naval!=null){ci.setReturnValue(Ndc01Item.deploy(c.getLevel(),c.getPlayer(),c.getHand(),naval).getResult());return;}var n=Wd01Item.container(c.getItemInHand());if(n!=null)ci.setReturnValue(Wd01Item.deploy(c.getLevel(),c.getPlayer(),c.getHand(),n).getResult());}
}
